const TARGET_POINTS = 90; // your sample has ~85; raise for more detail

// Parses M/m/L/l/z with implicit repeated coordinate pairs
function parse(d) {
  const t = d.match(/[a-zA-Z]|-?\d*\.?\d+(?:e[-+]?\d+)?/g);
  let i = 0, cmd, x = 0, y = 0;
  const pts = [];
  while (i < t.length) {
    if (/[a-zA-Z]/.test(t[i])) {
      cmd = t[i++];
      if (cmd === 'z' || cmd === 'Z') continue;
    }
    const a = +t[i++], b = +t[i++];
    if (cmd === 'M')      { x = a;  y = b;  cmd = 'L'; }
    else if (cmd === 'm') { x += a; y += b; cmd = 'l'; }
    else if (cmd === 'L') { x = a;  y = b; }
    else if (cmd === 'l') { x += a; y += b; }
    else throw new Error('Unsupported command: ' + cmd);
    pts.push([x, y]);
  }
  return pts;
}

// Ramer–Douglas–Peucker simplification
function rdp(p, eps) {
  if (p.length < 3) return p;
  const [x1, y1] = p[0], [x2, y2] = p[p.length - 1];
  const dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy) || 1e-9;
  let maxD = 0, idx = 0;
  for (let i = 1; i < p.length - 1; i++) {
    const d = Math.abs(dy * p[i][0] - dx * p[i][1] + x2 * y1 - y2 * x1) / len;
    if (d > maxD) { maxD = d; idx = i; }
  }
  if (maxD <= eps) return [p[0], p[p.length - 1]];
  return [...rdp(p.slice(0, idx + 1), eps).slice(0, -1), ...rdp(p.slice(idx), eps)];
}

function simplifyTo(pts, n) {
  let lo = 0, hi = 1000, best = pts;
  for (let k = 0; k < 30; k++) {
    const mid = (lo + hi) / 2, s = rdp(pts, mid);
    if (s.length > n) lo = mid; else { hi = mid; best = s; }
  }
  return best;
}

for (const [name, d] of Object.entries(PATHS)) {
  const raw = parse(d);
  const xs = raw.map(p => p[0]), ys = raw.map(p => p[1]);
  const minX = Math.min(...xs), maxX = Math.max(...xs);
  const minY = Math.min(...ys), maxY = Math.max(...ys);
  const w = maxX - minX, h = maxY - minY;

  const pts = simplifyTo(raw, TARGET_POINTS)
    .map(([x, y]) => `${(((x - minX) / w) * 100).toFixed(2)}% ${(((y - minY) / h) * 100).toFixed(2)}%`);

  console.log(`/* ${name} — aspect-ratio ${w.toFixed(1)} / ${h.toFixed(1)} */`);
  console.log(`.hero-video-frame--${name} {`);
  console.log(`  clip-path: polygon(${pts.join(', ')});`);
  console.log(`  aspect-ratio: ${w.toFixed(1)} / ${h.toFixed(1)};`);
  console.log(`}\n`);
}